<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms consent form</title>
    <style>
      :root {
        color-scheme: light;
        --color-bg: #eef2ff;
        --color-surface: #ffffff;
        --color-text: #111827;
        --color-muted: #4b5563;
        --color-primary: #4338ca;
        --color-primary-hover: #3730a3;
        --color-border: #c7d2fe;
        --color-border-strong: #6366f1;
        --color-error: #b91c1c;
        --color-success: #166534;
        --shadow-card: 0 24px 70px #312e8133;
        --radius-lg: 1.5rem;
        --radius-md: 0.875rem;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--color-text);
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 32rem),
          linear-gradient(135deg, var(--color-bg), #f8fafc);
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--color-primary);
        border-radius: 999px;
        transform: translateY(-150%);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #ffffff, 0 0 0 7px var(--color-primary);
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 31rem);
        padding: clamp(1.5rem, 6vw, 3rem);
        background: var(--color-surface);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-card);
      }

      .eyebrow {
        display: inline-flex;
        margin: 0 0 0.75rem;
        padding: 0.25rem 0.75rem;
        font-size: 0.8125rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        color: var(--color-primary-hover);
        text-transform: uppercase;
        background: #eef2ff;
        border-radius: 999px;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.2rem);
        line-height: 1.05;
        letter-spacing: -0.06em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--color-muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.25rem 0.875rem;
        padding: 1rem;
        background: #f8fafc;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
      }

      input[type="checkbox"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.15rem 0 0;
        accent-color: var(--color-primary);
      }

      input[type="checkbox"]:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #ffffff, 0 0 0 7px var(--color-border-strong);
      }

      label {
        font-weight: 700;
      }

      .required {
        font-weight: 800;
        color: var(--color-error);
      }

      .helper-text,
      .error-text {
        grid-column: 2;
        margin: 0;
        font-size: 0.9375rem;
      }

      .helper-text {
        color: var(--color-muted);
      }

      .error-text {
        display: none;
        color: var(--color-error);
        font-weight: 700;
      }

      .error-text.is-visible {
        display: block;
      }

      button {
        width: 100%;
        min-height: 3rem;
        padding: 0.85rem 1.2rem;
        font: inherit;
        font-weight: 800;
        color: #ffffff;
        background: var(--color-primary);
        border: 0;
        border-radius: var(--radius-md);
        cursor: pointer;
        transition:
          background-color 180ms ease,
          transform 180ms ease;
      }

      button:hover {
        background: var(--color-primary-hover);
      }

      button:active {
        transform: translateY(1px);
      }

      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #ffffff, 0 0 0 7px var(--color-border-strong);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-success);
        font-weight: 700;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        .form-field {
          background: Canvas;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .eyebrow,
        .skip-link,
        button {
          color: ButtonText;
          background: ButtonFace;
          border: 1px solid ButtonBorder;
        }

        .intro,
        .helper-text,
        .status,
        .required,
        .error-text {
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Consent required</p>
        <h1 id="page-title">Review and agree</h1>
        <p class="intro">
          Confirm that you accept the terms before continuing to your account.
        </p>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <input
              type="checkbox"
              id="terms"
              name="terms"
              required
              aria-describedby="terms-helper terms-error"
            >
            <label for="terms">
              I agree to the terms of use <span class="required" aria-hidden="true">*</span>
            </label>
            <p class="helper-text" id="terms-helper">
              Required to create and manage your account.
            </p>
            <p class="error-text" id="terms-error">
              Please agree to the terms of use before submitting.
            </p>
          </div>

          <button type="submit">Submit consent</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function setValidityState() {
        const isValid = checkbox.checked;
        checkbox.setAttribute("aria-invalid", String(!isValid));
        error.classList.toggle("is-visible", !isValid);
        return isValid;
      }

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          status.textContent = "";
        }

        setValidityState();
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        if (!setValidityState()) {
          checkbox.focus();
          return;
        }

        status.textContent = "Thanks. Your consent has been recorded.";
        form.reset();
        checkbox.removeAttribute("aria-invalid");
      });
    </script>
  </body>
</html>
